(()=>{
const canvases=[...document.querySelectorAll('.fx-canvas[data-effect="steam"]')];
if(!canvases.length)return;
const fine=matchMedia('(hover:hover) and (pointer:fine)').matches;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const V=`#version 300 es
in vec2 a;out vec2 uv;void main(){uv=a*.5+.5;gl_Position=vec4(a,0.,1.);}`;
const F=`#version 300 es
precision highp float;
in vec2 uv;out vec4 o;
uniform float time;uniform vec2 source;uniform vec2 mouse;uniform vec2 mvel;uniform float hasMouse;
float hash(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}
float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<4;i++){v+=a*noise(p);p=p*2.03+17.1;a*=.5;}return v;}
float filament(vec2 p,float off,float phase,float amp,float width){float rise=source.y-p.y;if(rise<0.||rise>.58)return 0.;float bend=sin(rise*15.+time*.72+phase)*amp+sin(rise*31.-time*.43+phase*1.7)*amp*.34;float md=distance(p,mouse);float push=hasMouse*exp(-md*md/0.018);bend+=push*(mvel.x*.0028+(p.y-mouse.y)*mvel.y*.0012);float cx=source.x+off+bend;float w=width+rise*.050;float d=abs(p.x-cx);float core=exp(-(d*d)/(w*w));float n=fbm(vec2((p.x+phase)*18.+time*.08,p.y*13.-time*.23));float cut=smoothstep(.25,.72,n+core*.30);float fade=smoothstep(0.,.035,rise)*(1.-smoothstep(.34,.58,rise));return core*cut*fade;}
void main(){vec2 p=vec2(uv.x,1.-uv.y);float s=0.;s+=filament(p,-.042,0.2,.020,.008);s+=filament(p,-.014,1.8,.027,.007);s+=filament(p,.015,3.2,.022,.007);s+=filament(p,.043,4.6,.018,.008);float halo=filament(p,0.,2.5,.035,.020)*.22;float a=clamp(s*.32+halo,0.,.46);vec3 col=mix(vec3(.76,.82,.86),vec3(1.),clamp(s,0.,1.));o=vec4(col,a);}`;
function make(c){const gl=c.getContext('webgl2',{alpha:true,antialias:false,premultipliedAlpha:false,preserveDrawingBuffer:true});if(!gl)return null;const sh=(t,s)=>{const x=gl.createShader(t);gl.shaderSource(x,s);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(x));return x};const p=gl.createProgram();gl.attachShader(p,sh(gl.VERTEX_SHADER,V));gl.attachShader(p,sh(gl.FRAGMENT_SHADER,F));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));const vao=gl.createVertexArray();gl.bindVertexArray(vao);const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const loc=gl.getAttribLocation(p,'a');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);const u={time:gl.getUniformLocation(p,'time'),source:gl.getUniformLocation(p,'source'),mouse:gl.getUniformLocation(p,'mouse'),mvel:gl.getUniformLocation(p,'mvel'),hasMouse:gl.getUniformLocation(p,'hasMouse')};const state={mouse:[.5,.5],mvel:[0,0],hasMouse:0};function resize(){const r=c.getBoundingClientRect();const w=r.width<700?180:256;c.width=w;c.height=Math.max(128,Math.round(w*r.height/r.width));gl.viewport(0,0,c.width,c.height)}resize();return{gl,p,vao,u,state,resize,draw(t,profile){gl.useProgram(p);gl.bindVertexArray(vao);gl.viewport(0,0,c.width,c.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);const src=profile==='tsubasa'?[.53,.58]:[.555,.575];gl.uniform1f(u.time,reduced?0:t*.001);gl.uniform2f(u.source,src[0],src[1]);gl.uniform2f(u.mouse,state.mouse[0],state.mouse[1]);gl.uniform2f(u.mvel,state.mvel[0],state.mvel[1]);gl.uniform1f(u.hasMouse,state.hasMouse);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.drawArrays(gl.TRIANGLES,0,3);gl.disable(gl.BLEND);state.mvel[0]*=.86;state.mvel[1]*=.86;}}}
const sims=[];
for(const c of canvases){let sim;try{sim=make(c)}catch(e){console.error(e)}if(!sim){c.style.display='none';continue}const s={c,sim,profile:c.dataset.profile,visible:false,lastPointer:null};sims.push(s);new IntersectionObserver(e=>s.visible=e[0].isIntersecting,{rootMargin:'120px'}).observe(c);if(fine){c.parentElement.addEventListener('pointermove',e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(x<0||x>1||y<0||y>1){sim.state.hasMouse=0;s.lastPointer=null;return}sim.state.mouse=[x,y];sim.state.hasMouse=1;if(s.lastPointer)sim.state.mvel=[e.clientX-s.lastPointer.x,e.clientY-s.lastPointer.y];s.lastPointer={x:e.clientX,y:e.clientY}},{passive:true});c.parentElement.addEventListener('pointerleave',()=>{sim.state.hasMouse=0;s.lastPointer=null},{passive:true})}}
addEventListener('resize',()=>sims.forEach(s=>s.sim.resize()),{passive:true});
let last=0;function frame(t){if(t-last>33){for(const s of sims)if(s.visible)s.sim.draw(t,s.profile);last=t}if(!reduced)requestAnimationFrame(frame)}
if(reduced){for(const s of sims)s.sim.draw(0,s.profile)}else requestAnimationFrame(frame);
window.__tsubasaEffects={engine:'webgl2-procedural-wispy-steam',effects:['steam','gpu-noise','multi-filament','pointer-flow'],interactive:fine,canvasCount:sims.length,targetFps:30,gpu:true};
})();